usageExample:
var block = new AgentLaneBlock("b1", "planner", DateTimeOffset.UtcNow, "Plan the release")
{
    End = DateTimeOffset.UtcNow.AddMinutes(8),
    Status = AgentActivityStatus.Succeeded,
    Kind = AgentLaneBlockKind.Task,
    Marker = AgentLaneBlockMarker.Approval,
};

// A block that is still running: no End, drawn up to the surface's "now".
var running = block with { Id = "b2", End = null, Status = AgentActivityStatus.Running, Marker = null };
